-- ─── D6. Close the terms of holders the city's current council page no longer lists ────────────────
UPDATE essentials.office_terms t
   SET term_end = v.te, how_ended = v.how, source = t.source || v.src
  FROM (VALUES
    ('929c3fff-b134-4c60-a761-c693290d4870'::uuid, '173f125c-0ec3-488e-8b74-ffd991e1a87b'::uuid, '2026-05-11'::date, 'resigned', ' | CA_0176: Eileen Wang resigned as Mayor and Council Member (District 3) on 2026-05-11 by letter to the City Manager (https://www.arcadiaca.gov/Document%20Center/Government/City%20Clerk/Agenda%20and%20Minutes/2026/2026-05-19_CC_Meeting_Agenda.pdf, staff report + Attachment 1).'),
    ('768a4d25-eed6-4d38-9fda-61ffc5020648'::uuid, '664b5518-3e28-4f8f-a42f-12fb6d627567'::uuid, '2025-01-28'::date, 'resigned', ' | CA_0176: David Torres (District 4) resigned as of 2025-01-28 (Jan 29 2025 minutes, https://montebelloca.api.civicclerk.com/v1/Meetings/GetMeetingFileStream(fileId=5995,plainText=false): "City Manager Alvarez announced the resignation of Councilmember David Torres as of January 28, 2025").'),
    ('cc02e1db-43d5-4e7a-9a72-4a33394f4b38'::uuid, '35f41c8d-0460-45c7-9e8c-28be5c42fb56'::uuid, '2024-12-05'::date, 'recalled', ' | CA_0176: Angie Jimenez (District 5) was recalled at the 2024-11-05 recall election; removed and the office deemed vacant effective 2024-12-05 (Resolution No. 24-89 staff report, https://montebelloca.api.civicclerk.com/v1/Meetings/GetMeetingFileStream(fileId=5818,plainText=false)).')
  ) AS v(oid, pid, te, how, src)
 WHERE t.office_id = v.oid AND t.politician_id = v.pid AND t.term_end IS NULL AND v.te IS NOT NULL;
UPDATE essentials.politicians p SET is_incumbent = false
 WHERE p.id IN ('173f125c-0ec3-488e-8b74-ffd991e1a87b', '664b5518-3e28-4f8f-a42f-12fb6d627567', '35f41c8d-0460-45c7-9e8c-28be5c42fb56')
   AND NOT EXISTS (SELECT 1 FROM essentials.office_current_holder och WHERE och.politician_id = p.id);

