-- ─── E1. Montebello elected City Clerk + City Treasurer (Carson pattern; on the LOCAL_EXEC place row) ────
INSERT INTO essentials.chambers (id, government_id, name, name_formal, policy_engagement_level)
SELECT v.id, (SELECT c.government_id FROM essentials.offices o JOIN essentials.chambers c ON c.id = o.chamber_id
               WHERE o.id = '0c7c275b-a8d2-4714-ac77-bc093f562974'), v.name, v.nf, 'full' FROM (VALUES
    ('27c5ca46-7147-4495-978c-d91400dd979d'::uuid, 'City Clerk', 'Montebello City Clerk'),
    ('8aac0489-29ae-426c-8555-abb0915d98f9'::uuid, 'City Treasurer', 'Montebello City Treasurer')
  ) AS v(id, name, nf) WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);
INSERT INTO essentials.offices (id, chamber_id, district_id, title, representing_state, seats, normalized_position_name,
                                is_appointed_position, is_vacant, faces_retention_vote, voting_powers)
SELECT v.oid, v.cid, '0a25cd5e-9dae-49b3-b3fb-004585e7de91'::uuid, v.title, 'CA', 1, v.title, false, false, false, 'full' FROM (VALUES
    ('7537adc6-76db-4036-8421-3c1a843ca5ad'::uuid, '27c5ca46-7147-4495-978c-d91400dd979d'::uuid, 'City Clerk'),
    ('5f208ba0-aadc-4189-9476-fd29777a0688'::uuid, '8aac0489-29ae-426c-8555-abb0915d98f9'::uuid, 'City Treasurer')
  ) AS v(oid, cid, title) WHERE NOT EXISTS (SELECT 1 FROM essentials.offices o WHERE o.id = v.oid);
INSERT INTO essentials.politicians (id, first_name, last_name, full_name, party, is_active, is_incumbent, is_vacant, is_appointed, data_source, alternate_names)
SELECT v.id, v.f, v.l, v.n, NULL, true, true, false, false, v.url, v.alt FROM (VALUES
    ('c03b0201-5e85-4dfb-b8e3-f71e138ee80d'::uuid, 'Christopher', 'Jimenez', 'Christopher Jimenez', 'https://www.montebelloca.gov/departments/administration/city_clerks_office', '{}'::text[]),
    ('6caa8b74-503d-4024-9bb0-9c514efa67eb'::uuid, 'David', 'Matanga', 'David Matanga', 'https://www.montebelloca.gov/government/elected_officials', '{}'::text[])
  ) AS v(id, f, l, n, url, alt) WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.id = v.id);
INSERT INTO essentials.office_terms (office_id, politician_id, term_start, start_precision, how_started, source)
SELECT v.oid, v.pid, v.ts, v.prec, v.how, v.src FROM (VALUES
    ('7537adc6-76db-4036-8421-3c1a843ca5ad'::uuid, 'c03b0201-5e85-4dfb-b8e3-f71e138ee80d'::uuid, NULL::date, 'unknown', 'elected', 'CA_0176: seated per https://www.montebelloca.gov/departments/administration/city_clerks_office (read 2026-09-23) -- City Clerk''s Office page: elected City Clerk Christopher Jimenez, term Nov 2024 - Nov 2028 (not a 2026 candidate).'),
    ('5f208ba0-aadc-4189-9476-fd29777a0688'::uuid, '6caa8b74-503d-4024-9bb0-9c514efa67eb'::uuid, '2022-12-14'::date, 'day', 'elected', 'CA_0176: seated per https://www.montebelloca.gov/government/elected_officials (read 2026-09-23) -- Elected Officials page lists David Matanga as City Treasurer; elected 2022-11-08 (LA County RR/CC 4300) and given the oath on 2022-12-14 (Dec 14 2022 minutes, https://montebelloca.api.civicclerk.com/v1/Meetings/GetMeetingFileStream(fileId=4663,plainText=false)).')
  ) AS v(oid, pid, ts, prec, how, src) WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = v.oid AND t.politician_id = v.pid);

-- ─── E2. Name fixes (2025 roster import put an honorific / a district in the name fields) ───────────
UPDATE essentials.politicians p SET full_name = v.fn, first_name = v.f, last_name = v.l,
       alternate_names = coalesce((SELECT array_agg(DISTINCT a) FROM unnest(coalesce(p.alternate_names, '{}'::text[]) || v.alt) a), '{}'::text[])
  FROM (VALUES
    ('45a74125-ebb2-475c-92c5-3f7d6f899f34'::uuid, 'Dr. Michael Cao', 'Michael Cao', 'Michael', 'Cao', ARRAY['Dr. Michael Cao', 'Michael Cao M.D.']::text[]),
    ('a3f864ad-c303-4549-8471-fd1a7519184c'::uuid, 'Janet Braun (District 5)', 'Janet Braun', 'Janet', 'Braun', '{}'::text[])
  ) AS v(id, old, fn, f, l, alt)
 WHERE p.id = v.id AND p.full_name = v.old;

-- ─── 0. Pre-flight: every binding target exists ───────────────────────────────────────
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (VALUES
    ('arcadia-council-district-2', 'LOCAL', NULL, 'Arcadia City Council District 2'),
    ('arcadia-council-district-3', 'LOCAL', NULL, 'Arcadia City Council District 3'),
    ('arcadia-council-district-5', 'LOCAL', NULL, 'Arcadia City Council District 5'),
    ('montebello-council-district-1', 'LOCAL', NULL, 'Montebello City Council District 1'),
    ('montebello-council-district-3', 'LOCAL', NULL, 'Montebello City Council District 3'),
    ('montebello-council-district-4', 'LOCAL', NULL, 'Montebello City Council District 4 (Unexpired Term Ending 2028)'),
    ('montebello-council-district-5', 'LOCAL', NULL, 'Montebello City Council District 5'),
    ('0648816', 'LOCAL_EXEC', 'City Treasurer', 'Montebello City Treasurer'),
    ('south-pasadena-council-district-4', 'LOCAL', NULL, 'South Pasadena City Council District 4'),
    ('azusa-council-district-1', 'LOCAL', NULL, 'Azusa City Council District 1'),
    ('azusa-council-district-3', 'LOCAL', NULL, 'Azusa City Council District 3'),
    ('duarte-council-district-1', 'LOCAL', NULL, 'Duarte City Council District 1')
  ) AS v(place, dtype, otitle, pos)
   WHERE NOT EXISTS (SELECT 1 FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                      WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle));
  IF n <> 0 THEN RAISE EXCEPTION 'pre-flight: % race(s) with no office to bind to', n; END IF;
END $$;

-- ─── 1. Races ─────────────────────────────────────────────────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, t.office_id, t.pos, NULL, t.seats
  FROM (SELECT v.pos, v.seats,
               (SELECT o.id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                 WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle)
                 ORDER BY o.id LIMIT 1) AS office_id
          FROM (VALUES
    ('arcadia-council-district-2', 'LOCAL', NULL, 'Arcadia City Council District 2', 1),
    ('arcadia-council-district-3', 'LOCAL', NULL, 'Arcadia City Council District 3', 1),
    ('arcadia-council-district-5', 'LOCAL', NULL, 'Arcadia City Council District 5', 1),
    ('montebello-council-district-1', 'LOCAL', NULL, 'Montebello City Council District 1', 1),
    ('montebello-council-district-3', 'LOCAL', NULL, 'Montebello City Council District 3', 1),
    ('montebello-council-district-4', 'LOCAL', NULL, 'Montebello City Council District 4 (Unexpired Term Ending 2028)', 1),
    ('montebello-council-district-5', 'LOCAL', NULL, 'Montebello City Council District 5', 1),
    ('0648816', 'LOCAL_EXEC', 'City Treasurer', 'Montebello City Treasurer', 1),
    ('south-pasadena-council-district-4', 'LOCAL', NULL, 'South Pasadena City Council District 4', 1),
    ('azusa-council-district-1', 'LOCAL', NULL, 'Azusa City Council District 1', 1),
    ('azusa-council-district-3', 'LOCAL', NULL, 'Azusa City Council District 3', 1),
    ('duarte-council-district-1', 'LOCAL', NULL, 'Duarte City Council District 1', 1)
          ) AS v(place, dtype, otitle, pos, seats)) t
 WHERE t.office_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = t.pos);

