  ) AS v(pos, full_name, first_name, last_name, pid, inc, desig, src)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 3. Antipartisan: clear the stored party on every linked candidate row ──────────
UPDATE essentials.politicians SET party = NULL
 WHERE party IS NOT NULL AND id IN ('2ac8d60b-37b7-4d79-85a9-174896fa1375', '2ffdbaa3-2d1e-4c16-89e8-26d50fd1e509', '32a292f3-2386-4576-936a-1109698c37fe', '45a74125-ebb2-475c-92c5-3f7d6f899f34', '47d39500-15ae-4aee-bb7b-30615f89cbac', '55cc57ed-a9c0-4303-80ff-35309b9b968a', '6caa8b74-503d-4024-9bb0-9c514efa67eb', '7e14a7c0-50dc-43ee-81b6-b86ae1ed10dc', '93696676-f698-4bc9-a844-df8d5a0171c5', 'a260ceae-23cb-4bd2-aa3d-780921b8b588', 'bdd20cfe-31f9-4931-af6a-7ed1d9eab917');

-- ─── 4. Post-verify gate ──────────────────────────────────────────────────────────────
DO $$
DECLARE
  pos text[] := ARRAY['Arcadia City Council District 2', 'Arcadia City Council District 3', 'Arcadia City Council District 5', 'Montebello City Council District 1', 'Montebello City Council District 3', 'Montebello City Council District 4 (Unexpired Term Ending 2028)', 'Montebello City Council District 5', 'Montebello City Treasurer', 'South Pasadena City Council District 4', 'Azusa City Council District 1', 'Azusa City Council District 3', 'Duarte City Council District 1'];
  n_races int; n_cands int; n_null int; n_party int; n_badcount int; n_inc int; n_badinc int; n_extralink int; n_linked int; n_incseat int;
  n_overinc int; n_unreach int; n_pparty int; n_dpoly int; n_seatok int; n_dbad int; n_size int; n_dleak int; n_mn int; n_gone int; n_fix int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL), count(*) FILTER (WHERE r.primary_party IS NOT NULL)
    INTO n_races, n_null, n_party FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_cands FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  -- each race carries exactly the clerk's field, on the expected seat count
  SELECT count(*) INTO n_badcount FROM (VALUES
      ('Arcadia City Council District 2', 1, 2, 1),
      ('Arcadia City Council District 3', 1, 3, 1),
      ('Arcadia City Council District 5', 1, 2, 1),
      ('Montebello City Council District 1', 1, 4, 1),
      ('Montebello City Council District 3', 1, 3, 0),
      ('Montebello City Council District 4 (Unexpired Term Ending 2028)', 1, 2, 1),
      ('Montebello City Council District 5', 1, 2, 1),
      ('Montebello City Treasurer', 1, 1, 1),
      ('South Pasadena City Council District 4', 1, 2, 1),
      ('Azusa City Council District 1', 1, 3, 0),
      ('Azusa City Council District 3', 1, 2, 0),
      ('Duarte City Council District 1', 1, 2, 1)
    ) AS v(pos, seats, n_cand, n_inc)
    LEFT JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
   WHERE r.id IS NULL OR r.seats <> v.seats
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id) <> v.n_cand
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) <> v.n_inc;
  -- incumbents: linked, and holding THIS race's own seat (for a district race: that district's office)
  -- any linked candidate (incl. a sitting official running for another seat): a current holder somewhere in the city
  SELECT count(*) FILTER (WHERE rc.is_incumbent),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NULL),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND (d2.geo_id = cm.place OR (cm.pat <> '' AND d2.geo_id LIKE cm.pat)
                   OR d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))
    INTO n_inc, n_badinc, n_extralink, n_linked, n_incseat
    FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN (VALUES
      ('Arcadia City Council District 2', '0602462', 'arcadia-council-district-%'),
      ('Arcadia City Council District 3', '0602462', 'arcadia-council-district-%'),
      ('Arcadia City Council District 5', '0602462', 'arcadia-council-district-%'),
      ('Montebello City Council District 1', '0648816', 'montebello-council-district-%'),
      ('Montebello City Council District 3', '0648816', 'montebello-council-district-%'),
      ('Montebello City Council District 4 (Unexpired Term Ending 2028)', '0648816', 'montebello-council-district-%'),
      ('Montebello City Council District 5', '0648816', 'montebello-council-district-%'),
      ('Montebello City Treasurer', '0648816', 'montebello-council-district-%'),
      ('South Pasadena City Council District 4', '0673220', 'south-pasadena-council-district-%'),
      ('Azusa City Council District 1', '0603386', 'azusa-council-district-%'),
      ('Azusa City Council District 3', '0603386', 'azusa-council-district-%'),
      ('Duarte City Council District 1', '0619990', 'duarte-council-district-%')
    ) AS cm(cpos, place, pat) ON cm.cpos = r.position_name
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_overinc FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) > r.seats;
  -- END TO END: an interior point of each race's own polygon reaches that race
  SELECT count(*) INTO n_unreach FROM essentials.races r
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.geofence_boundaries me ON me.geo_id = d.geo_id AND me.mtfcc = d.mtfcc
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
                        AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry)));
  SELECT count(*) INTO n_pparty FROM essentials.politicians p WHERE p.party IS NOT NULL AND p.id IN (
    SELECT rc.politician_id FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
     WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND rc.politician_id IS NOT NULL);
  IF n_races <> 12 THEN RAISE EXCEPTION 'expected 12 races, got %', n_races; END IF;
  IF n_cands <> 28 THEN RAISE EXCEPTION 'expected 28 candidates, got %', n_cands; END IF;
  IF n_null <> 0 OR n_party <> 0 THEN RAISE EXCEPTION 'office-less (%) or partisan (%) race', n_null, n_party; END IF;
  IF n_badcount <> 0 THEN RAISE EXCEPTION '% race(s) whose seats / candidates / incumbents differ from the clerk list', n_badcount; END IF;
  IF n_inc <> 9 THEN RAISE EXCEPTION 'expected 9 incumbents, got %', n_inc; END IF;
  IF n_badinc <> 0 THEN RAISE EXCEPTION '% incumbent(s) left unlinked', n_badinc; END IF;
  IF n_extralink <> 0 THEN RAISE EXCEPTION '% linked candidate(s) are not a current holder in their city', n_extralink; END IF;
  IF n_linked <> 11 THEN RAISE EXCEPTION 'expected 11 linked candidates, got %', n_linked; END IF;
  IF n_incseat <> 0 THEN RAISE EXCEPTION '% incumbent(s) do not hold the seat their race is for', n_incseat; END IF;
  IF n_overinc <> 0 THEN RAISE EXCEPTION '% race(s) with more incumbents than seats', n_overinc; END IF;
  IF n_unreach <> 0 THEN RAISE EXCEPTION '% race(s) not reached from inside their own city', n_unreach; END IF;
  IF n_pparty <> 0 THEN RAISE EXCEPTION '% linked candidate row(s) still carry a party', n_pparty; END IF;
  -- every new district row resolves to its polygon
  SELECT count(*) INTO n_dpoly FROM essentials.districts d JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc
   WHERE d.district_type = 'LOCAL' AND d.id IN ('fe8dceb7-e1ff-4c32-b185-63fcd855b834', 'ee0e1c8c-38c5-4b9e-8596-07548189386a', '1682e3c4-e3d6-4ad7-808c-4642c22030cb', '104fe207-8d20-4951-9b50-e44c47c4c3cc', '06f68d97-f393-4d0f-90eb-561e44dcb779', 'e5501549-308e-438a-bd49-8881471eb453', '6d9389fc-6a90-45ec-bc6f-8447400e84b3', 'c8b5f901-dae0-415a-a912-931ba8db9b81', '95a71376-2945-4f44-ae4f-a7ec8b9c12d3', '55567893-1b49-4e55-912c-80b9bae33909', '69939ee4-3ea4-4baa-8fae-1d6855a6ced1', 'b04d1976-4820-447e-9e01-ae77dce21d50', 'a7e12818-3e5d-465b-b0d5-df3a173d6961', 'c1756aea-5bed-4e7e-b02a-2698e41f3ba6', '06e891d9-7d6e-4a37-91e1-3138ed69d92f', '4cacb3bf-0ff3-4c57-a301-856cfe0ce1e9', '246c7847-da4d-4e49-89be-b2a5290d5f7f', '9b92b875-9742-4eab-b5b8-418744114407', '9e251eba-1bec-4b7b-9d34-b3cf2ac4cc73', 'f3fe5e35-62c7-4f79-ba24-7635d768de79', '95e07fa6-81c1-4704-9d42-1eec109741da', '4f16dd24-b959-468c-b7d8-7685d99c31a8', '477d8086-dd6d-4a8f-8ffd-4ad131aafa7a', '6cf5ee94-def9-4ec3-802a-c24a94e6c1d3', 'd61f22cb-6a15-49c0-8de4-e4787594126d', 'f962768b-e36e-468a-8a83-4c8e77614bf6', '81079a5a-e389-445f-b7af-c4fcbfefa27a');
  -- every seat sits where it should, with its title, held by the named member (or flagged vacant)
  SELECT count(*) INTO n_seatok FROM (VALUES
      ('805c620c-ecfd-48f9-9fd8-c73d916dfde1'::uuid, 'fb1f120a-8821-4649-a209-03b6b77e0105'::uuid, 'arcadia-council-district-1', 'Council Member (District 1)'),
      ('5e6ef860-0c76-4d60-8c94-709b66ca44a7'::uuid, 'bdd20cfe-31f9-4931-af6a-7ed1d9eab917'::uuid, 'arcadia-council-district-2', 'Council Member (District 2)'),
      ('929c3fff-b134-4c60-a761-c693290d4870'::uuid, '47d39500-15ae-4aee-bb7b-30615f89cbac'::uuid, 'arcadia-council-district-3', 'Council Member (District 3)'),
      ('4c379f6c-7f70-4cc2-a3a2-c40d9a6a56a4'::uuid, '72add1da-a898-4789-ab17-f41ec7260bc5'::uuid, 'arcadia-council-district-4', 'Council Member (District 4)'),
      ('4109138f-57be-42de-90ce-aa1b0de3fbb3'::uuid, '45a74125-ebb2-475c-92c5-3f7d6f899f34'::uuid, 'arcadia-council-district-5', 'Council Member (District 5)'),
      ('0c7c275b-a8d2-4714-ac77-bc093f562974'::uuid, '2ffdbaa3-2d1e-4c16-89e8-26d50fd1e509'::uuid, 'montebello-council-district-1', 'Council Member (District 1)'),
      ('3888a303-692e-4ce0-8dbe-bf56ca959790'::uuid, '60ba761c-1695-46af-b56f-7881a5b8df4a'::uuid, 'montebello-council-district-2', 'Council Member (District 2)'),
      ('0b4acc5b-df21-47cc-94bc-c1e6bf7f9998'::uuid, 'bb6b1993-83ba-46cc-b725-271cca6f206d'::uuid, 'montebello-council-district-3', 'Council Member (District 3)'),
      ('768a4d25-eed6-4d38-9fda-61ffc5020648'::uuid, '32a292f3-2386-4576-936a-1109698c37fe'::uuid, 'montebello-council-district-4', 'Council Member (District 4)'),
      ('cc02e1db-43d5-4e7a-9a72-4a33394f4b38'::uuid, '2ac8d60b-37b7-4d79-85a9-174896fa1375'::uuid, 'montebello-council-district-5', 'Council Member (District 5)'),
      ('19f1be22-5957-43c5-8c38-ac8e4ac626c0'::uuid, '01317eb5-e154-4d54-b7f4-fc87c8be935d'::uuid, 'south-pasadena-council-district-1', 'Council Member (District 1)'),
      ('9dab5153-0854-4f7b-b1b8-17a890e668e2'::uuid, '329fd1b9-271a-42a1-a31e-52fb43cb0caa'::uuid, 'south-pasadena-council-district-2', 'Council Member (District 2)'),
      ('897a2101-e962-405e-a7ef-510987a0d440'::uuid, '8c3558a7-b2bc-41d4-882d-ddb3fe0a45bb'::uuid, 'south-pasadena-council-district-3', 'Council Member (District 3)'),
      ('1bc6472e-c9e2-49cc-8105-cac9ad93d78f'::uuid, '7e14a7c0-50dc-43ee-81b6-b86ae1ed10dc'::uuid, 'south-pasadena-council-district-4', 'Council Member (District 4)'),
      ('22a7a848-8ad3-4de3-8d9a-8c8b14b65726'::uuid, 'a3f864ad-c303-4549-8471-fd1a7519184c'::uuid, 'south-pasadena-council-district-5', 'Council Member (District 5)'),
      ('d53ec2a9-a2d1-4337-bbf9-ed34abbae1b2'::uuid, '55cc57ed-a9c0-4303-80ff-35309b9b968a'::uuid, NULL, 'Council Member (At-Large)'),
      ('74c49af6-457a-4d37-b33d-93fc30a8ef1e'::uuid, 'a260ceae-23cb-4bd2-aa3d-780921b8b588'::uuid, NULL, 'Council Member (At-Large)'),
      ('fc44e99e-c574-4549-9417-ae7ad5a7884d'::uuid, NULL::uuid, 'azusa-council-district-1', 'Council Member (District 1)'),
      ('459ea4ad-c30b-4b1e-a43f-fb4e4f69ab70'::uuid, '4244252f-7230-4a45-90b5-1a76754b8d60'::uuid, 'azusa-council-district-2', 'Council Member (District 2)'),
      ('77b1b1ea-60a1-434d-84af-281b60836a3e'::uuid, NULL::uuid, 'azusa-council-district-3', 'Council Member (District 3)'),
      ('206f1cc9-d799-46de-9209-85840d3ce294'::uuid, '8f1b8a6c-a248-41a1-baa1-f7462c874bb5'::uuid, 'azusa-council-district-4', 'Council Member (District 4)'),
      ('291b440f-2633-4f47-a1bf-a6305c11ea7c'::uuid, 'f7a3197c-c73a-4170-9a2d-174f6434c142'::uuid, 'azusa-council-district-5', 'Council Member (District 5)'),
      ('22f1ba53-cbaa-44c6-add1-3d3a10e2a73f'::uuid, '93696676-f698-4bc9-a844-df8d5a0171c5'::uuid, 'duarte-council-district-1', 'Council Member (District 1)'),
      ('338f9291-8f73-486d-8c90-ac7303c9220f'::uuid, '40d785ea-d43f-4c8e-a418-d657dd5b8052'::uuid, 'duarte-council-district-2', 'Council Member (District 2)'),
      ('ad3396df-d536-408e-bfb1-15d179e83c8d'::uuid, '00762a8d-57aa-475e-ad3b-3298ded47fa2'::uuid, 'duarte-council-district-3', 'Council Member (District 3)'),
      ('eb8f1d13-4264-45a8-82de-77386e24abd3'::uuid, '750e4783-6247-4fab-b172-7a2924e1e3c0'::uuid, 'duarte-council-district-4', 'Council Member (District 4)'),
      ('b0ac76d2-45e5-4c29-824d-4d316330310e'::uuid, '8450dc6a-9514-45fc-8c22-3f545fe6a028'::uuid, 'duarte-council-district-5', 'Council Member (District 5)'),
      ('ceda0241-24cd-44d2-a3b2-fcb6fa00faf1'::uuid, '32a054c8-990a-4cad-a7d4-86964b42b402'::uuid, 'duarte-council-district-6', 'Council Member (District 6)'),
      ('1dee2a12-f20a-4ca8-bc0c-df85497ff59d'::uuid, '6102d132-196e-468b-b989-515966ed5c21'::uuid, 'duarte-council-district-7', 'Council Member (District 7)')
    ) AS v(oid, pid, dgeo, title)
    JOIN essentials.offices o ON o.id = v.oid AND o.title = v.title
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE (v.dgeo IS NULL OR d.geo_id = v.dgeo)
     AND ((v.pid IS NOT NULL AND och.politician_id = v.pid) OR (v.pid IS NULL AND och.politician_id IS NULL AND o.is_vacant));
  -- each district row carries exactly one office
  SELECT count(*) INTO n_dbad FROM essentials.districts d WHERE d.id IN ('fe8dceb7-e1ff-4c32-b185-63fcd855b834', 'ee0e1c8c-38c5-4b9e-8596-07548189386a', '1682e3c4-e3d6-4ad7-808c-4642c22030cb', '104fe207-8d20-4951-9b50-e44c47c4c3cc', '06f68d97-f393-4d0f-90eb-561e44dcb779', 'e5501549-308e-438a-bd49-8881471eb453', '6d9389fc-6a90-45ec-bc6f-8447400e84b3', 'c8b5f901-dae0-415a-a912-931ba8db9b81', '95a71376-2945-4f44-ae4f-a7ec8b9c12d3', '55567893-1b49-4e55-912c-80b9bae33909', '69939ee4-3ea4-4baa-8fae-1d6855a6ced1', 'b04d1976-4820-447e-9e01-ae77dce21d50', 'a7e12818-3e5d-465b-b0d5-df3a173d6961', 'c1756aea-5bed-4e7e-b02a-2698e41f3ba6', '06e891d9-7d6e-4a37-91e1-3138ed69d92f', '4cacb3bf-0ff3-4c57-a301-856cfe0ce1e9', '246c7847-da4d-4e49-89be-b2a5290d5f7f', '9b92b875-9742-4eab-b5b8-418744114407', '9e251eba-1bec-4b7b-9d34-b3cf2ac4cc73', 'f3fe5e35-62c7-4f79-ba24-7635d768de79', '95e07fa6-81c1-4704-9d42-1eec109741da', '4f16dd24-b959-468c-b7d8-7685d99c31a8', '477d8086-dd6d-4a8f-8ffd-4ad131aafa7a', '6cf5ee94-def9-4ec3-802a-c24a94e6c1d3', 'd61f22cb-6a15-49c0-8de4-e4787594126d', 'f962768b-e36e-468a-8a83-4c8e77614bf6', '81079a5a-e389-445f-b7af-c4fcbfefa27a')
     AND (SELECT count(*) FROM essentials.offices o WHERE o.district_id = d.id) <> 1;
  -- each council has exactly its expected number of sitting members (place + its districts)
  SELECT count(*) INTO n_size FROM (VALUES
      ('0602462', 'arcadia-council-district-%', 5),
      ('0648816', 'montebello-council-district-%', 5),
      ('0673220', 'south-pasadena-council-district-%', 5),
      ('0603386', 'azusa-council-district-%', 5),
      ('0619990', 'duarte-council-district-%', 7)
    ) AS v(place, pat, size)
   WHERE (SELECT count(DISTINCT och.politician_id) FROM essentials.districts d JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE d.district_type IN ('LOCAL', 'LOCAL_EXEC') AND (d.geo_id = v.place OR d.geo_id LIKE v.pat)
             AND o.title NOT IN ('City Clerk', 'City Treasurer')) = v.size;
  -- NO CROSS-LEAK: an interior point of every district reaches exactly its own district race (if up) or none
  SELECT count(*) INTO n_dleak FROM (
    SELECT a.geo_id, a.up, (SELECT count(*) FROM essentials.races r
        JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
        JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
       WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND r.position_name LIKE '%District%'
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry))) AS hits
      FROM (VALUES
      ('arcadia-council-district-1', 0),
      ('arcadia-council-district-2', 1),
      ('arcadia-council-district-3', 1),
      ('arcadia-council-district-4', 0),
      ('arcadia-council-district-5', 1),
      ('montebello-council-district-1', 1),
      ('montebello-council-district-2', 0),
      ('montebello-council-district-3', 1),
      ('montebello-council-district-4', 1),
      ('montebello-council-district-5', 1),
      ('south-pasadena-council-district-1', 0),
      ('south-pasadena-council-district-2', 0),
      ('south-pasadena-council-district-3', 0),
      ('south-pasadena-council-district-4', 1),
      ('south-pasadena-council-district-5', 0),
      ('azusa-council-district-1', 1),
      ('azusa-council-district-2', 0),
      ('azusa-council-district-3', 1),
      ('azusa-council-district-4', 0),
      ('azusa-council-district-5', 0),
      ('duarte-council-district-1', 1),
      ('duarte-council-district-2', 0),
      ('duarte-council-district-3', 0),
      ('duarte-council-district-4', 0),
      ('duarte-council-district-5', 0),
      ('duarte-council-district-6', 0),
      ('duarte-council-district-7', 0)
      ) AS a(geo_id, up) JOIN essentials.geofence_boundaries me ON me.geo_id = a.geo_id AND me.mtfcc = 'X0001') x
   WHERE x.hits <> x.up;
  IF n_dpoly <> 27 THEN RAISE EXCEPTION 'districts: % of 27 new district rows resolve to a polygon', n_dpoly; END IF;
  IF n_seatok <> 29 THEN RAISE EXCEPTION 'seats: % of 29 seats in place with their named holder', n_seatok; END IF;
  IF n_dbad <> 0 THEN RAISE EXCEPTION '% district row(s) without exactly one office', n_dbad; END IF;
  IF n_size <> 5 THEN RAISE EXCEPTION 'councils: % of 5 at their expected size', n_size; END IF;
  IF n_dleak <> 0 THEN RAISE EXCEPTION '% district(s) reach the wrong number of district races', n_dleak; END IF;
  SELECT count(*) INTO n_mn FROM (VALUES ('7537adc6-76db-4036-8421-3c1a843ca5ad'::uuid, 'c03b0201-5e85-4dfb-b8e3-f71e138ee80d'::uuid), ('5f208ba0-aadc-4189-9476-fd29777a0688'::uuid, '6caa8b74-503d-4024-9bb0-9c514efa67eb'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n_mn <> 2 THEN RAISE EXCEPTION 'Montebello: % of 2 clerk/treasurer seats held', n_mn; END IF;
  -- the three departed holders no longer hold any seat
  SELECT count(*) INTO n_gone FROM essentials.office_current_holder och WHERE och.politician_id IN ('173f125c-0ec3-488e-8b74-ffd991e1a87b', '664b5518-3e28-4f8f-a42f-12fb6d627567', '35f41c8d-0460-45c7-9e8c-28be5c42fb56');
  IF n_gone <> 0 THEN RAISE EXCEPTION '% departed holder(s) still seated', n_gone; END IF;
  SELECT count(*) INTO n_fix FROM essentials.politicians WHERE (id, full_name) IN (('45a74125-ebb2-475c-92c5-3f7d6f899f34'::uuid, 'Michael Cao'), ('a3f864ad-c303-4549-8471-fd1a7519184c'::uuid, 'Janet Braun'));
  IF n_fix <> 2 THEN RAISE EXCEPTION 'name fixes: % of 2 applied', n_fix; END IF;
  RAISE NOTICE 'CA_0176 applied: % races, % candidates, % incumbents linked', n_races, n_cands, n_inc;
END $$;

COMMIT;
